test('native full cohort matches original Storage metadata and preserves immutable receipt',async()=>{await reset();await locked(async db=>{const result=await db.reconcileUnknownPrefix(request()),current=identity(template()),versions=sourceRows.slice(0,120).map(row=>row.version).sort(),facts=owner.readNativeSchemaStageAdmission(result.permit,current,versions);assert.equal(facts.inventory.totalStorageObjects,3);assert.equal(facts.target.authUsers,0);assert.equal(facts.expectedVersions.length,120);assert.equal(state.creates,1);const stored=state.vault;facts.inventory.totalStorageObjects=0;assert.equal(owner.readNativeSchemaStageAdmission(result.permit,current,versions).inventory.totalStorageObjects,3);await db.refreshReconciliationPermit(result.permit,current,120);assert.throws(()=>owner.readNativeSchemaStageAdmission(result.permit,current,versions),'minimal journal refresh invalidates full cohort');assert.equal(state.vault,stored);});});

test('native cohort drains held Storage siblings before its final quiescence and refuses drift without publishing facts',async()=>{
 await reset();let release!:()=>void;state.storageHold=new Promise<void>(done=>release=done);const db=await database();let finished=false;const pending=db.withLock(projectRef+':HOSTED_SCHEMA_MIGRATION',async()=>{const result=await db.reconcileUnknownPrefix(request());owner.readNativeSchemaStageAdmission(result.permit,identity(template()),sourceRows.slice(0,120).map(row=>row.version).sort());}).then(()=>{finished=true;});
 try{for(let index=0;index<1000&&(!state.events.includes('cohort-native-catalogue')||!state.cohortStorageHeld);index++)await new Promise<void>(done=>setTimeout(done,20));assert.ok(state.cohortStorageHeld,'Storage work overlaps serial native collection');assert.ok(state.events.includes('cohort-native-catalogue'));assert.equal(state.events.includes('cohort-quiescence'),false,'final quiescence waits for Storage drain');assert.equal(finished,false);release();await pending;assert.equal(state.events.includes('cohort-quiescence'),true);}finally{release();await pending.catch(()=>undefined);}
 await reset();await locked(async current=>{const result=await current.reconcileUnknownPrefix(request()),versions=sourceRows.slice(0,120).map(row=>row.version).sort(),original=state.vault;state.nativeMetadataDrift=true;state.nativeSnapshots=0;await assert.rejects(current.refreshSchemaStageAdmission(result.permit,identity(template()),versions));assert.throws(()=>owner.readNativeSchemaStageAdmission(result.permit,identity(template()),versions));assert.equal(state.vault,original);assert.equal(state.creates,1);});
});

test('native cohort obtains complete PRE and POST Storage and target metadata in one bounded statement per phase',async()=>{await reset();await locked(async db=>{await db.reconcileUnknownPrefix(request());assert.equal(state.queries.filter(sql=>sql.includes('CUEVO_NATIVE_STORAGE_SNAPSHOT')).length,2);assert.equal(state.queries.some(sql=>/CUEVO_NATIVE_STORAGE_(COUNTS|BUCKETS|OBJECTS)/.test(sql)),false);});});


test('version two null fingerprint cohort publishes actual native reconciliation permit and retains the original receipt',async()=>{await reset();await locked(async db=>{const input=request(template(),true),result=await db.reconcileUnknownPrefix(input),current=identity(template()),facts=owner.readNativeSchemaStageAdmission(result.permit,current,sourceRows.slice(0,120).map(row=>row.version).sort());assert.equal(facts.authority.expected.fingerprints.apiArtifactSha256,null);assert.equal(facts.authority.expected.fingerprints.edgeArtifactSha256,null);assert.equal(facts.authority.expected.fingerprints.denoLockSha256,null);assert.equal(state.creates,1);const stored=state.vault;await db.refreshReconciliationPermit(result.permit,current,120);assert.equal(owner.readNativeMigrationPermitAuthority(result.permit,current).expected.fingerprints.apiArtifactSha256,null);assert.equal(state.vault,stored);});});
